import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import "./optimizevideo.css";

const Optimizevideo_shortform = () => {
    const location = useLocation();
    const [videoPath, setVideoPath] = useState("");
    const [message, setMessage] = useState("");
    const [enhancementType, setEnhancementType] = useState("");

    useEffect(() => {
        if (location.state) {
            const { results = {} } = location.state;
            console.log("Received Results:", results);

            // Get the first clip's data
            const clipData = Object.values(results)[0] || {};
            const fileName = Object.keys(results)[0];

            console.log("Clip Data:", clipData);
            console.log("File Name:", fileName);

            // Extract enhancement paths
            const audioEnhancedPath = clipData.audio_processing?.enhanced_video_path;
            const videoEnhancedPath = clipData.video_upscaling?.processed_file_path;

            console.log("Audio Enhanced Path:", audioEnhancedPath);
            console.log("Video Enhanced Path:", videoEnhancedPath);

            let selectedPath = "";

            // Determine which enhancement to use (prioritize video upscaling)
            if (audioEnhancedPath) {

                selectedPath = audioEnhancedPath;
                setEnhancementType("Audio Enhanced");

            } else if (videoEnhancedPath) {
                selectedPath = videoEnhancedPath;
                setEnhancementType("Video Enhanced");
            } else {
                selectedPath = fileName;
                setEnhancementType("Original Video");
            }

            if (selectedPath) {
                // Extract filename from path, handling both forward and backward slashes
                const filename = selectedPath.split(/[/\\]/).pop();

                if (filename) {
                    // Remove any additional processing suffixes for the URL
                    const baseFilename = filename.replace(/_IRCNN.*\.mp4$/, '.mp4');
                    setVideoPath(`http://127.0.0.1:8000/media/${baseFilename}`);
                    setMessage("Video processing completed successfully!");
                    console.log("Final Video Path:", `http://127.0.0.1:8000/media/${baseFilename}`);
                }
            } else {
                setMessage("No processed video available.");
            }
        }
    }, [location.state]);

    const handleDownload = () => {
        if (videoPath) {
            const link = document.createElement("a");
            link.href = videoPath;
            link.download = "optimized-shortform-video.mp4";
            link.click();
        }
    };

    return (
        <div className="optimized-video-page">
            <header className="page-header">
                <h1>Optimized Short-form Video</h1>
                <p>{message}</p>
            </header>

            <div className="enhancement-info">
                <span className="enhancement-badge">
                    {enhancementType}
                </span>
            </div>

            <div className="video-output">
                {videoPath ? (
                    <>
                        <video className="optimized-video" controls src={videoPath}>
                            Your browser does not support the video tag.
                        </video>
                        <div className="video-info">
                            <div className="action-buttons">
                                <button
                                    className="download-button"
                                    onClick={handleDownload}
                                >
                                    Download Video
                                </button>
                            </div>
                        </div>
                    </>
                ) : (
                    <div className="no-video">
                        <p>No optimized video available.</p>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Optimizevideo_shortform;
